@Service
@Transactional(readOnly = true)
@RequiredArgsConstructor
public class OrderQueryService {

    private final OrderRepository orderRepository;

    public List<OrderDto> findOrders(int offset, int limit) {
        return orderRepository.findAllWithMemberDelivery(offset, limit)
                .stream()
                .map(OrderDto::new)      // 여기가 트랜잭션 안이다
                .toList();
    }
}

@GetMapping("/api/v3.1/orders")
public Result ordersV31(
        @RequestParam(value = "offset", defaultValue = "0") int offset,
        @RequestParam(value = "limit", defaultValue = "100") int limit) {

    return new Result(orderQueryService.findOrders(offset, limit));
}

